  "inlineSchema": "// Club Management System Database Schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../lib/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// User model - for authentication (admin and members)\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String\n  role      String   @default(\"member\") // \"admin\" or \"member\"\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  profile  MemberProfile?\n  payments Payment[]\n  expenses Expense[]\n}\n\nenum TeamCategory {\n  JUNIOR\n  SENIOR\n  GUEST\n}\n\n// Member Profile model - additional info for members\nmodel MemberProfile {\n  id           String   @id @default(cuid())\n  userId       String   @unique\n  name         String\n  phone        String?\n  email        String?\n  bloodGroup   String?\n  jerseySize   String?\n  jerseyNumber String?\n  address      String?\n  bio          String?\n  joiningDate  DateTime @default(now())\n  imageUrl     String?\n\n  playsFootball    Boolean @default(true)\n  footballPosition String?\n\n  playsCricket Boolean @default(false)\n  cricketRole  String?\n  rating       Float   @default(0)\n\n  teamCategory TeamCategory @default(JUNIOR)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  participants Participant[]\n}\n\n// Event model - for generic events (picnic, Eid reunion, etc.)\nmodel Event {\n  id          String   @id @default(cuid())\n  name        String\n  description String?\n  eventDate   DateTime\n  location    String?\n  type        String\n  budget      Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  payments     Payment[]\n  expenses     Expense[]\n  galleryItems GalleryItem[]\n  participants Participant[]\n}\n\n// Match model - for sports matches\nmodel Match {\n  id        String   @id @default(cuid())\n  name      String\n  opponent  String\n  matchDate DateTime\n  location  String?\n  matchType String // \"friendly\", \"league\", \"tournament\", etc.\n  result    String? // \"win\", \"loss\", \"draw\", null if not played yet\n  score     String? // e.g., \"3-2\"\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  payments     Payment[]\n  expenses     Expense[]\n  galleryItems GalleryItem[]\n  participants Participant[]\n}\n\n// Tournament model - for tournament management\nmodel Tournament {\n  id          String   @id @default(cuid())\n  name        String\n  startDate   DateTime\n  endDate     DateTime\n  location    String?\n  entryFee    Float    @default(0)\n  totalPrize  Float    @default(0)\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  positions    TournamentPosition[]\n  payments     Payment[]\n  expenses     Expense[]\n  galleryItems GalleryItem[]\n  participants Participant[]\n}\n\n// Tournament Position model - for tournament results\nmodel TournamentPosition {\n  id           String   @id @default(cuid())\n  tournamentId String\n  position     Int // 1st, 2nd, 3rd, etc.\n  teamName     String\n  prize        Float    @default(0)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Relations\n  tournament Tournament @relation(fields: [tournamentId], references: [id], onDelete: Cascade)\n}\n\n// Payment model - for member collections\nmodel Payment {\n  id          String   @id @default(cuid())\n  userId      String\n  amount      Float\n  purpose     String // \"iftary\", \"match\", \"event\", \"tournament\", \"monthly\", \"other\"\n  description String?\n  paymentDate DateTime @default(now())\n  month       String? // \"January\", \"February\", etc. for monthly payments\n  year        Int? // For monthly payments\n  status      String   @default(\"paid\") // \"paid\", \"pending\", \"cancelled\"\n\n  // Relations to events/matches/tournaments (optional)\n  eventId      String?\n  matchId      String?\n  tournamentId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user       User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  event      Event?      @relation(fields: [eventId], references: [id], onDelete: SetNull)\n  match      Match?      @relation(fields: [matchId], references: [id], onDelete: SetNull)\n  tournament Tournament? @relation(fields: [tournamentId], references: [id], onDelete: SetNull)\n}\n\n// Expense model - for expense tracking\nmodel Expense {\n  id          String   @id @default(cuid())\n  userId      String\n  amount      Float\n  category    String // \"food\", \"jersey\", \"ground-rent\", \"transport\", \"equipment\", \"other\"\n  description String\n  expenseDate DateTime @default(now())\n\n  // Relations to events/matches/tournaments (optional)\n  eventId      String?\n  matchId      String?\n  tournamentId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user       User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  event      Event?      @relation(fields: [eventId], references: [id], onDelete: SetNull)\n  match      Match?      @relation(fields: [matchId], references: [id], onDelete: SetNull)\n  tournament Tournament? @relation(fields: [tournamentId], references: [id], onDelete: SetNull)\n}\n\n// Gallery model - for event/match photos\nmodel GalleryItem {\n  id          String  @id @default(cuid())\n  title       String\n  imageUrl    String\n  description String?\n\n  // Relations to events/matches/tournaments\n  eventId      String?\n  matchId      String?\n  tournamentId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  event      Event?      @relation(fields: [eventId], references: [id], onDelete: SetNull)\n  match      Match?      @relation(fields: [matchId], references: [id], onDelete: SetNull)\n  tournament Tournament? @relation(fields: [tournamentId], references: [id], onDelete: SetNull)\n}\n\n// Participant model - for many-to-many relationships between members and events/matches/tournaments\nmodel Participant {\n  id        String @id @default(cuid())\n  profileId String\n\n  // Relations to events/matches/tournaments\n  eventId      String?\n  matchId      String?\n  tournamentId String?\n\n  status    String   @default(\"pending\") // \"pending\", \"joined\", \"attended\", \"not-attended\"\n  joinedAt  DateTime @default(now())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  profile    MemberProfile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  event      Event?        @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  match      Match?        @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  tournament Tournament?   @relation(fields: [tournamentId], references: [id], onDelete: Cascade)\n\n  // Composite unique with nullable columns doesn't prevent duplicates in Postgres,\n  // so enforce uniqueness per participation type.\n  @@unique([profileId, eventId])\n  @@unique([profileId, matchId])\n  @@unique([profileId, tournamentId])\n}\n",
